Of course. Here is a well-structured and optimized JSX script for Adobe InDesign that accomplishes the requested transformation.

This script creates a **new document** with a single long page, preserving the original. This is a much safer approach than modifying the original document directly.

### Key Features of the Script:

*   **Safe Operation:** It creates a new document, leaving your original file untouched.
*   **Optimized for Speed:** It disables screen redraw during the main process and re-enables it at the end, which dramatically improves performance on large documents.
*   **Handles Spreads:** Correctly calculates the position of elements on both left-hand and right-hand pages of a spread.
*   **Preserves Master Page Content:** It "bakes in" the master page items by overriding them onto each page before copying. This is the only way to maintain their appearance and position on a single page, as a single page can only have one master applied.
*   **Accurate Positioning:** It meticulously calculates the new vertical and horizontal positions for every single element.
*   **Undoable:** The entire script is wrapped in a single `doScript` call, so you can undo the entire operation with a single `Ctrl+Z` (or `Cmd+Z`).
*   **User-Friendly:** Provides clear alerts for errors (like no document being open) and on completion.

---

### The JSX Script

Save the following code as a `.jsx` file (e.g., `transformToSinglePage.jsx`).

```javascript
// transformToSinglePage.jsx
// Copyright 2023
// This script transforms a multi-page/spread InDesign document into a new, single-page document.
// It preserves the layout, element positioning, and visual appearance of master page items.

#target indesign

// Main function wrapped in an IIFE (Immediately Invoked Function Expression) for safe scope
(function () {

    // 1. SCRIPT SETUP AND VALIDATION
    // =========================================================================

    if (app.documents.length === 0) {
        alert("Error: No document is open.\nPlease open the document you wish to transform and run the script again.");
        return;
    }

    var originalDoc = app.activeDocument;

    if (originalDoc.pages.length <= 1) {
        alert("Information: The active document has only one page. No action is needed.");
        return;
    }

    // Wrap the entire logic in a single undo step for easy reversal
    app.doScript(main, ScriptLanguage.JAVASCRIPT, [], UndoModes.ENTIRE_SCRIPT, "Transform to Single Page");

    // 2. MAIN LOGIC
    // =========================================================================

    function main() {
        // --- PREPARATION ---

        // Disable screen redraw for a massive performance boost
        app.scriptPreferences.enableRedraw = false;

        // --- DATA COLLECTION ---

        var originalPages = originalDoc.pages;
        var totalHeight = 0;
        var pageWidth, pageHeight;
        var margins;

        // Get properties from the first page to define the new document's layout
        var firstPage = originalPages[0];
        pageWidth = firstPage.bounds[3] - firstPage.bounds[1];
        margins = {
            top: firstPage.marginPreferences.top,
            left: firstPage.marginPreferences.left,
            bottom: firstPage.marginPreferences.bottom,
            right: firstPage.marginPreferences.right
        };

        // Calculate the total height required for the new single page
        for (var i = 0; i < originalPages.length; i++) {
            totalHeight += originalPages[i].bounds[2] - originalPages[i].bounds[0];
        }

        // --- NEW DOCUMENT CREATION ---

        var newDoc = app.documents.add();
        newDoc.documentPreferences.facingPages = false;
        newDoc.documentPreferences.pagesPerDocument = 1;

        // Apply collected properties to the new page
        var newPage = newDoc.pages[0];
        newPage.marginPreferences.properties = margins;

        // Set the page size using geometric bounds [y1, x1, y2, x2]
        // y1, x1 are top-left; y2, x2 are bottom-right
        newPage.bounds = [0, 0, totalHeight, pageWidth];


        // --- CONTENT MIGRATION ---

        var yOffset = 0; // This will track the vertical position for the next page's content

        // Loop through all spreads in the original document
        for (var s = 0; s < originalDoc.spreads.length; s++) {
            var currentSpread = originalDoc.spreads[s];

            // Loop through each page within the current spread
            for (var p = 0; p < currentSpread.pages.length; p++) {
                var currentPage = currentSpread.pages[p];

                // Vital Step: Override all master page items onto the current page.
                // This makes them accessible as regular page items so they can be moved.
                // We use a try/catch block in case a page has no master or items.
                try {
                    var masterItems = currentPage.appliedMaster.pageItems;
                    for (var m = 0; m < masterItems.length; m++) {
                        masterItems[m].override(currentPage);
                    }
                } catch (e) {
                    // This page likely has no master or no items on the master. Continue.
                }


                var allItemsOnPage = currentPage.allPageItems;
                if (allItemsOnPage.length === 0) {
                     // If page is blank, just update the yOffset and continue
                     yOffset += currentPage.bounds[2] - currentPage.bounds[0];
                     continue;
                }

                // Duplicate all items from the current page to the new document's single page
                var duplicatedItems = [];
                for (var i = 0; i < allItemsOnPage.length; i++) {
                    // We must check if the item is a group, a pageItem doesn't belong to a group
                    // or if its parent is the page itself to avoid duplicating child items of a group multiple times
                    if(allItemsOnPage[i].parent instanceof Page){
                         duplicatedItems.push(allItemsOnPage[i].duplicate(newPage));
                    }
                }

                // Now, move the duplicated items to their correct new position
                for (var j = 0; j < duplicatedItems.length; j++) {
                    var item = duplicatedItems[j];
                    var itemBounds = item.geometricBounds; // [y1, x1, y2, x2]

                    var itemHeight = itemBounds[2] - itemBounds[0];
                    var itemWidth = itemBounds[3] - itemBounds[1];

                    // The item's original horizontal (x) position is relative to the spread's zero point.
                    // We need to make it relative to the page's zero point.
                    // currentPage.bounds[1] is the left edge of the page on the spread.
                    // For a left page, this is 0. For a right page, it's (pageWidth + gutter).
                    // Subtracting this value normalizes the horizontal position.
                    var newX = itemBounds[1] - currentPage.bounds[1];

                    // The new vertical (y) position is its original position plus the offset of all previous pages.
                    var newY = itemBounds[0] + yOffset;

                    // Move the item by setting its new geometricBounds
                    item.geometricBounds = [newY, newX, newY + itemHeight, newX + itemWidth];
                }

                // Update the vertical offset for the next page's content
                yOffset += currentPage.bounds[2] - currentPage.bounds[0]; // page height
            }
        }

        // --- CLEANUP ---

        // Re-enable screen redraw
        app.scriptPreferences.enableRedraw = true;

        // Fit the new page in the window to show the result
        app.activeWindow.activePage = newDoc.pages[0];
        app.activeWindow.zoom(ZoomOptions.FIT_PAGE);
    }

    alert("Transformation complete!\nA new document has been created with a single long page.");

})();
```

### How to Install and Use the Script

1.  **Open the Scripts Panel in InDesign:**
    *   Go to `Window` > `Utilities` > `Scripts`.

2.  **Locate the User Scripts Folder:**
    *   In the Scripts panel, right-click (or Ctrl-click on Mac) on the `User` folder.
    *   Select `Reveal in Finder` (on Mac) or `Reveal in Explorer` (on Windows).

3.  **Install the Script:**
    *   Copy the `.jsx` file you saved into this `User` folder.

4.  **Run the Script:**
    *   Go back to InDesign. The script will now appear in the Scripts panel under the `User` folder.
    *   Open the InDesign document you want to transform.
    *   Double-click the script name (`transformToSinglePage.jsx`) in the Scripts panel.
    *   The script will execute and create a new document with the single-page layout.

